import "core-js/modules/es.array.push.js";
import api from '../services/api';
export default {
  name: 'StoreOwnerLogin',
  data() {
    return {
      credentials: {
        username: '',
        password: ''
      },
      registerData: {
        username: '',
        email: '',
        password: '',
        full_name: '',
        store_name: '',
        phone: '',
        address: ''
      },
      error: '',
      loading: false,
      showRegisterForm: false
    };
  },
  methods: {
    async handleLogin() {
      this.error = '';
      this.loading = true;
      try {
        const response = await api.post('/admin/auth/login/store-owner', this.credentials);
        this.$store.dispatch('login', {
          user: response.data.user,
          token: response.data.token
        });
        this.$router.push('/store-owner/dashboard');
      } catch (err) {
        this.error = err.response?.data?.message || 'Login failed. Please try again.';
      } finally {
        this.loading = false;
      }
    },
    async handleRegister() {
      try {
        const response = await api.post('/admin/auth/register/store-owner', this.registerData);
        alert(response.data.message);
        this.showRegisterForm = false;
        this.registerData = {
          username: '',
          email: '',
          password: '',
          full_name: '',
          store_name: '',
          phone: '',
          address: ''
        };
      } catch (err) {
        alert(err.response?.data?.message || 'Registration failed');
      }
    }
  }
};
